import { Badge, type BadgeTone } from '@absoluteui/components/badge';

const row = document.createElement('p');
document.body.append(row);
const statuses: [string, BadgeTone][] = [['Draft', 'neutral'], ['In review', 'info'], ['Active', 'success'], ['Expiring', 'warning'], ['Overdue', 'error']];
for (const [label, tone] of statuses) {
  const host = document.createElement('span');
  row.append(host, ' ');
  Badge.create(host, { label, tone, dot: true });
}

import { Badge } from '@absoluteui/components/badge';

const heading = document.createElement('h3');
heading.textContent = 'Release notes ';
const beta = document.createElement('span');
heading.append(beta);
document.body.append(heading);
Badge.create(beta, { label: 'Beta', tone: 'info', variant: 'outline', size: 'sm', icon: 'info' });
